export function generateStaticParams() {
  return DATA.map((item) => ({ slug: item.slug }));
}

export function generateMetadata({ params }: { params: { slug: string } }): Metadata {
  const item = DATA.find((d) => d.slug === params.slug) ?? DATA[0];
  return {
    title: item.title,
    description: item.desc,
    keywords: [
      ...BASE_KW,
      item.slug.replace(/-/g, ""),
      item.h1.replace(/[— ]/g, ""),
    ],
    openGraph: {
      title: item.title,
      description: item.desc,
      url: `https://jeomun.com/movie/guide/${item.slug}`,
      siteName: "점운 인생영화",
      locale: "ko_KR",
      type: "website",
    },
    alternates: { canonical: `https://jeomun.com/movie/guide/${item.slug}` },
  };
}

